/* @lc app=leetcode id=2007 lang=kotlin */
class Solution { fun findOriginalArray(changed: IntArray): IntArray = if (changed.size % 2 != 0) intArrayOf() else IntArray(100001).also { c -> changed.forEach { c[it]++ } }.let { c -> changed.sortedArray().filter { x -> (c[x] > 0 && x * 2 <= 100000 && c[x * 2] > 0 && (x != 0 || c[x] >= 2)).also { if (it) c.apply { this[x]-- }.apply { this[x * 2]-- } } }.toIntArray().let { res -> if (res.size == changed.size / 2) res else intArrayOf() } } }